"""The FIPS reference index generated by web/scripts/build-geo.mjs."""

import json
from pathlib import Path

from .models import County, State


class Reference:
    def __init__(self, reference_dir: Path):
        counties = json.loads((reference_dir / "counties.json").read_text())
        states = json.loads((reference_dir / "states.json").read_text())
        self.counties: dict[str, County] = {c["fips"]: County.model_validate(c) for c in counties}
        self.states: dict[str, State] = {s["fips"]: State.model_validate(s) for s in states}
